#!/usr/bin/env bash
# parity_bench.sh — per-call Snowflake fallback for Phase 4 (parity) +
# Phase 5 (benchmark). Session variables don't survive across sessions
# in per-call clients (snowsql -q, altimate-code one-shot), so the run
# id is generated by the shell and interpolated into literal table
# names. A trap guarantees the DROPs run even on Ctrl-C or non-zero
# exit — the parity scratch tables may contain PII.
#
# Usage: parity_bench.sh <orig_sql_file> <opt_sql_file>
#   env:  SNOWFLAKE_RUN_SQL    command that runs stdin as Snowflake SQL
#                              (e.g. 'snowsql -c <conn>'  or
#                              'altimate-code run' wrapped — see docs).
#         SQO_DEV_SCHEMA       REQUIRED — user's own dev schema (e.g.
#                              DEV_<USER>). The parity tables materialise
#                              the full result sets; writing them to a
#                              shared schema would expose that data to
#                              anyone with USAGE on the schema.

set -euo pipefail

ORIG_SQL="${1:?original SQL file required}"
OPT_SQL="${2:?optimised SQL file required}"

: "${SNOWFLAKE_RUN_SQL:?SNOWFLAKE_RUN_SQL command required, e.g. snowsql -c myconn}"
: "${SQO_DEV_SCHEMA:?SQO_DEV_SCHEMA required — use the caller own dev schema, never a shared one}"

# Shell-generated RUN_ID → interpolated into literal table names → always
# available for the DROP. The old 'SET parity_orig = ...' approach ran
# in session 1 and the DROP in session 2 and failed with "session
# variable does not exist".
RUN_ID="$(uuidgen 2>/dev/null | tr -d - | tr a-z A-Z || date +%s%N)"
ORIG_TABLE="${SQO_DEV_SCHEMA}._SQO_ORIG_${RUN_ID}"
OPT_TABLE="${SQO_DEV_SCHEMA}._SQO_OPT_${RUN_ID}"

cleanup() {
  local rc=$?
  # Always try to clean up — never leave the PII-bearing scratch tables
  # behind. Suppress output; if the DROP itself fails (session gone), the
  # tables are TRANSIENT with TTL=0, so Snowflake reaps them, but we try
  # anyway.
  printf 'DROP TABLE IF EXISTS %s;\nDROP TABLE IF EXISTS %s;\n' "$ORIG_TABLE" "$OPT_TABLE" \
    | $SNOWFLAKE_RUN_SQL >/dev/null 2>&1 || true
  exit "$rc"
}
trap cleanup EXIT INT TERM

# Materialise each side once, with cache off.
{
  printf 'ALTER SESSION SET USE_CACHED_RESULT = FALSE;\n'
  printf 'CREATE OR REPLACE TRANSIENT TABLE %s AS\n' "$ORIG_TABLE"
  cat "$ORIG_SQL"
  printf ';\n'
  printf 'CREATE OR REPLACE TRANSIENT TABLE %s AS\n' "$OPT_TABLE"
  cat "$OPT_SQL"
  printf ';\n'
} | $SNOWFLAKE_RUN_SQL

echo "parity_bench.sh: scratch tables materialised"
echo "  original : $ORIG_TABLE"
echo "  optimised: $OPT_TABLE"
echo "Run parity SQL against those table names, then exit — the trap drops both."
